const DEFAULT_QR_B64 = "data:image/png;base64,";
        let countdownInterval = null;
        let timerSeconds = 12;

        window.addEventListener('DOMContentLoaded', () => {
            const dateInput = document.getElementById('meal-date');
            const timeInput = document.getElementById('meal-time');
            
            // Set defaults to match the exact recording
            dateInput.value = '2026-10-13';
            timeInput.value = '14:11';
        });

        function toggleAdvanced() {
            const adv = document.getElementById('advanced-fields');
            adv.style.display = adv.style.display === 'block' ? 'none' : 'block';
        }

        function formatDate(dateStr) {
            if (!dateStr) return 'Oct 13, 2026';
            const parts = dateStr.split('-');
            if (parts.length === 3) {
                const date = new Date(parts[0], parts[1] - 1, parts[2]);
                const options = { month: 'short', day: 'numeric', year: 'numeric' };
                return date.toLocaleDateString('en-US', options);
            }
            return dateStr;
        }

        function formatTime(timeStr) {
            if (!timeStr) return '02:11 PM';
            let [hour, minute] = timeStr.split(':');
            hour = parseInt(hour, 10);
            const ampm = hour >= 12 ? 'PM' : 'AM';
            hour = hour % 12 || 12;
            const hourFormatted = hour < 10 ? '0' + hour : hour;
            return `${hourFormatted}:${minute} ${ampm}`;
        }

        function generatePass() {
            const meal = document.getElementById('meal-type').value || 'Lunch';
            const dateVal = document.getElementById('meal-date').value;
            const timeVal = document.getElementById('meal-time').value;

            const name = document.getElementById('student-name')?.value || 'Jaskeerat Singh';
            const id = document.getElementById('student-id')?.value || '12505487';
            const mess = document.getElementById('mess-centre')?.value || 'Mess-Centre-02';
            const verif = document.getElementById('verif-code')?.value || '22939453';
            const timerVal = parseInt(document.getElementById('timer-seconds')?.value, 10) || 12;

            // Update text elements
            document.getElementById('display-meal').innerText = meal;
            document.getElementById('display-date').innerText = formatDate(dateVal);
            document.getElementById('display-time').innerText = formatTime(timeVal);
            document.getElementById('display-student-name').innerText = name;
            document.getElementById('display-student-id').innerText = id;
            document.getElementById('display-mess-centre').innerText = mess;
            document.getElementById('display-assigned-mess').innerText = `Your Assigned Mess - ${mess}`;
            document.getElementById('display-verif-code').innerText = verif;

            document.getElementById('coupon-user-name').innerText = `${name} ${id}`;

            // Update QR code:
            const qrImg = document.getElementById('pass-qr-img');
            const qrDyn = document.getElementById('qrcode-dynamic');

            if (meal === 'Lunch' && dateVal === '2026-10-13') {
                qrImg.style.display = 'block';
                qrDyn.style.display = 'none';
                qrImg.src = DEFAULT_QR_B64;
            } else {
                if (typeof QRCode !== 'undefined') {
                    qrImg.style.display = 'none';
                    qrDyn.style.display = 'block';
                    qrDyn.innerHTML = '';
                    new QRCode(qrDyn, {
                        text: `5ckgwlvQ79Bgtm5io09Y0Bxt2A5pJK5q/qKBs9fmA8c=_${meal}_${dateVal}`,
                        width: 120,
                        height: 120,
                        colorDark: '#000000',
                        colorLight: '#ffffff',
                        correctLevel: QRCode.CorrectLevel.M
                    });
                } else {
                    qrImg.style.display = 'block';
                    qrDyn.style.display = 'none';
                    qrImg.src = DEFAULT_QR_B64;
                }
            }

            // Switch view to Mess Coupon screen underneath
            document.getElementById('selection-screen').style.display = 'none';
            document.getElementById('mess-coupon-screen').style.display = 'block';

            // Open Pass Sheet Modal
            timerSeconds = timerVal;
            openPassModal();
        }

        function openPassModal() {
            const overlay = document.getElementById('pass-modal-overlay');
            overlay.style.display = 'block';
            
            // Trigger slide-up transition
            setTimeout(() => {
                overlay.classList.add('active');
            }, 20);

            // Start Countdown Timer
            startCountdown();
        }

        function closePassSheet() {
            const overlay = document.getElementById('pass-modal-overlay');
            overlay.classList.remove('active');
            clearInterval(countdownInterval);

            // Wait for slide-down animation to finish
            setTimeout(() => {
                overlay.style.display = 'none';
            }, 420);
        }

        function startCountdown() {
            clearInterval(countdownInterval);
            let current = timerSeconds;
            const timerEl = document.getElementById('countdown-timer');
            timerEl.innerText = current;

            countdownInterval = setInterval(() => {
                current--;
                if (current >= 0) {
                    timerEl.innerText = current;
                }
                if (current <= 0) {
                    clearInterval(countdownInterval);
                    // Automatically slide down when reaching 0, exactly as in screen recording
                    setTimeout(() => {
                        closePassSheet();
                    }, 500);
                }
            }, 1000);
        }

        function openPassWithMeal(meal) {
            document.getElementById('meal-type').value = meal;
            document.getElementById('display-meal').innerText = meal;
            
            // Re-open pass modal sheet
            const timerVal = parseInt(document.getElementById('timer-seconds')?.value, 10) || 12;
            timerSeconds = timerVal;
            openPassModal();
        }

        function backToSelection() {
            closePassSheet();
            document.getElementById('mess-coupon-screen').style.display = 'none';
            document.getElementById('selection-screen').style.display = 'flex';
        }